<template>
  <div class="traffic-dashboard" data-activity-private>
    <header class="traffic-header">
      <div class="traffic-masthead"><span class="traffic-kicker"><svg viewBox="0 0 20 20" aria-hidden="true"><circle v-for="n in 9" :key="n" :cx="3+((n-1)%3)*7" :cy="3+Math.floor((n-1)/3)*7" r="1.6"/></svg> Observations</span><span class="traffic-status"><i/>{{ privateMode ? 'Owner view' : 'Public overview' }}</span></div>
      <h1>Website traffic<button class="traffic-owner-dot" :aria-label="privateMode?'Go to owner workspace':'Owner access'" data-press-intent="custom" @click="openOwner"><span aria-hidden="true">.</span></button></h1><p>A closer look at how people find this site and spend time here.</p>
    </header>
    <div class="traffic-toolbar"><div class="traffic-periods" role="group" aria-label="Reporting period"><button v-for="period in [7,30,90,365]" :key="period" :aria-pressed="days===period" @click="days=period;load()">{{ period===365?'1 year':`${period} days` }}</button></div><div class="traffic-toolbar-end"><span v-if="report" class="traffic-date">{{ date(report.start) }} – {{ date(report.end) }}</span><button class="traffic-icon-button" aria-label="Refresh traffic" :disabled="busy" @click="load"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M16 8a6 6 0 1 0-.8 6M16 3v5h-5"/></svg></button></div></div>
    <p v-if="error" class="traffic-error" role="alert">{{ error }} <button class="traffic-text-button" @click="load">Try again</button></p>
    <div v-if="!report && busy" class="traffic-loading" role="status"><div class="loading-dots"><i v-for="n in 24" :key="n" :style="{'--i':n}"/></div>Gathering the latest visits</div>
    <div v-if="report" class="traffic-content" :class="{'is-updating':busy}" :aria-busy="busy">
      <div class="traffic-metrics"><button v-for="item in metrics" :key="item.key" :class="['traffic-metric',{active:metric===item.key}]" :aria-pressed="metric===item.key" @click="metric=item.key"><span>{{ item.label }}</span><strong>{{ item.format(report.summary[item.key]) }}</strong><small>{{ comparison(item.key) }}</small><svg v-if="metric===item.key" viewBox="0 0 12 12" aria-hidden="true"><circle cx="6" cy="6" r="2"/></svg></button></div>
      <section class="traffic-trend traffic-panel"><header class="panel-heading"><h2>{{ currentMetric.label }} over time</h2><span>Daily · {{ timezoneLabel }}</span></header><TrafficChart :series="report.series" :metric="metric" :label="currentMetric.label"/><p v-if="report.collection_started_at && report.collection_started_at>report.start" class="traffic-note">Detailed collection began {{ date(report.collection_started_at) }}. Earlier days in this range have no site records.</p></section>
      <div class="traffic-geography traffic-panel">
        <section><header class="panel-heading"><h2>Where visits begin</h2><span>{{ report.countries.length }} countries and regions</span></header>
          <TrafficWorld :countries="report.countries" :selected="selectedCountry" @select="selectCountry"/>
          <div class="country-detail" aria-live="polite"><template v-if="countryDetail"><strong>{{ countryName(countryDetail.country) }}</strong><span>{{ number(countryDetail.count) }} sessions</span><span>{{ duration(countryDetail.visible_ms) }} active</span></template><span v-else>Select a country to see its visits.</span></div>
          <p class="traffic-note">Locations reflect the visitor’s network, at country level.</p>
        </section>
        <section class="country-ranking"><div class="ranking-head"><span>Country / region</span><span>Sessions</span></div><ol><li v-for="row in visibleCountries" :key="row.country"><button :aria-pressed="selectedCountry===row.country" @click="selectCountry(row.country)"><span>{{ countryName(row.country) }}</span><strong>{{ number(row.count) }}</strong><i :style="{width:barWidth(row.count,report.countries)}"/></button></li></ol><p v-if="!report.countries.length" class="traffic-empty">Country data will appear with new visits.</p><button v-if="report.countries.length>7" class="traffic-text-button ranking-expand" :aria-expanded="allCountries" @click="allCountries=!allCountries">{{ allCountries?'Show fewer':`All ${report.countries.length} countries and regions` }}<svg viewBox="0 0 12 12" aria-hidden="true"><path :d="allCountries?'m2 8 4-4 4 4':'m2 4 4 4 4-4'"/></svg></button></section>
      </div>
      <div class="traffic-breakdowns"><section v-for="group in breakdowns" :key="group.title" class="traffic-panel traffic-ranking"><header class="panel-heading"><h2>{{ group.title }}</h2><span>{{ group.unit }}</span></header><div v-if="group.title==='Devices'" class="traffic-device-tabs" role="group" aria-label="Device breakdown"><button v-for="option in technologyOptions" :key="option.key" :aria-pressed="technology===option.key" @click="technology=option.key">{{ option.label }}</button></div><ol><li v-for="row in expandedRankings[group.key]?group.rows:group.rows.slice(0,8)" :key="row[group.key]"><div class="ranking-row"><span :title="friendly(row[group.key])">{{ friendly(row[group.key]) }}</span><strong>{{ number(row.count) }}</strong><i :style="{width:barWidth(row.count,group.rows)}"/></div></li></ol><p v-if="!group.rows.length" class="traffic-empty">New activity will appear here.</p><button v-if="group.rows.length>8" class="traffic-text-button ranking-expand" :aria-expanded="!!expandedRankings[group.key]" @click="expandedRankings[group.key]=!expandedRankings[group.key]">{{ expandedRankings[group.key]?'Show fewer':`Show all ${group.rows.length}` }}<svg viewBox="0 0 12 12" aria-hidden="true"><path :d="expandedRankings[group.key]?'m2 8 4-4 4 4':'m2 4 4 4 4-4'"/></svg></button></section></div>
      <div class="traffic-bottom-grid"><section class="traffic-panel"><header class="panel-heading"><h2>{{ report.presentations.length ? 'Time spent exploring' : 'Time on pages' }}</h2><span>{{ report.presentations.length ? 'Foreground time' : 'Active engagement' }}</span></header><ol class="experience-list"><li v-for="row in engagementRows" :key="row.presentation"><span class="experience-symbol" :data-kind="row.presentation"/><div><strong>{{ friendly(row.presentation) }}</strong><small>{{ row.sessions }} sessions</small></div><span>{{ duration(row.visible_ms) }}</span></li></ol><p v-if="!engagementRows.length" class="traffic-empty">Reading and exhibition time will appear here as visits accumulate.</p></section><section class="traffic-panel"><header class="panel-heading"><h2>When people visit</h2><span>{{ timezoneLabel }}</span></header><div class="traffic-hours"><div v-for="day in 7" :key="day" class="hours-row"><span>{{ ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][day-1] }}</span><div v-for="hour in 24" :key="hour" :style="{'--intensity':hourIntensity(day%7,hour-1)}" :title="`${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][day%7]} ${hour-1}:00 ${timezoneLabel} · ${hourValue(day%7,hour-1)} sessions`"/></div><div class="hours-axis"><span>00</span><span>06</span><span>12</span><span>18</span></div></div><p class="traffic-note">Sessions beginning in each hour.</p></section></div>
      <TrafficOwner v-if="privateMode" ref="ownerWorkspace" :report="report" :filters="filters" :filter-busy="filterBusy" :filter-error="filterError" @refresh="load" @filter="setFilter"/>
    </div>
    <footer class="traffic-footer">
      <details>
        <summary>About these numbers<svg viewBox="0 0 12 12" aria-hidden="true"><path d="M1 6h10"/><path d="M6 1v10"/></svg></summary>
        <p>Sessions count visits to henryw.me during the selected period. Time on site measures how long visitors actively view the site.</p>
        <p v-if="report?.generated_at">Updated {{ new Date(report.generated_at).toLocaleString('en') }}</p>
      </details>
      <button v-if="privateMode" class="traffic-text-button" @click="signOut">Leave owner view</button>
    </footer>
    <Teleport to="body"><div v-if="loginOpen" class="traffic-login-backdrop" @click.self="closeLogin" @keydown.esc="closeLogin"><form ref="loginForm" class="traffic-login" role="dialog" aria-modal="true" aria-labelledby="traffic-login-heading" data-activity-private @submit.prevent="login" @keydown.tab="trapLogin"><button type="button" class="login-close" aria-label="Close owner access" @click="closeLogin"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 5 10 10M15 5 5 15"/></svg></button><span class="traffic-kicker">Private workspace</span><h2 id="traffic-login-heading">Welcome back.</h2><p>Sign in to explore visitor journeys and feedback.</p><label for="traffic-password">Owner password</label><input id="traffic-password" ref="passwordInput" v-model="password" type="password" autocomplete="current-password" required/><p v-if="loginError" role="alert">{{ loginError }}</p><button class="login-submit" :disabled="loginBusy">{{ loginBusy?'Signing in…':'Enter owner view' }}<ArrowUpRightIcon/></button></form></div></Teleport>
  </div>
</template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue';
import TrafficChart from './traffic/TrafficChart.vue';
import TrafficWorld from './traffic/TrafficWorld.vue';
import TrafficOwner from './traffic/TrafficOwner.vue';
import {getTrafficDashboard,loginSharedViewsAdmin,hasSharedViewsAdminSession,clearSharedViewsAdminSession,setTrafficExclusion} from '../utils/viewShareSite';
import {countryName} from '../utils/visitorContextLabel';
import {excludeOwnerBrowser} from '../utils/analyticsPolicy';
import {lockBodyScroll} from '../utils/bodyScrollLock';
const report=ref(null),days=ref(30),metric=ref('sessions'),busy=ref(false),error=ref(''),privateMode=ref(false),filters=ref({});
const selectedCountry=ref(''),allCountries=ref(false),expandedRankings=ref({}),filterBusy=ref(false),filterError=ref(''),ownerWorkspace=ref(null);
const countryDetail=computed(()=>report.value?.countries.find(row=>row.country===selectedCountry.value));
const visibleCountries=computed(()=>{const rows=report.value?.countries||[];if(allCountries.value)return rows;const first=rows.slice(0,7);if(countryDetail.value&&!first.includes(countryDetail.value))return [...first.slice(0,6),countryDetail.value];return first;});
const loginOpen=ref(false),password=ref(''),loginBusy=ref(false),loginError=ref(''),passwordInput=ref(null),loginForm=ref(null);
let controller,disposed=false,returnFocus=null,releaseScroll=null;
const number=value=>Number(value||0).toLocaleString('en');
const duration=ms=>{const s=Math.round((ms||0)/1000);return s<60?`${s}s`:s<3600?`${Math.floor(s/60)}m ${s%60}s`:`${Math.floor(s/3600)}h ${Math.floor(s%3600/60)}m`;};
const date=value=>new Date(value).toLocaleDateString('en',{month:'short',day:'numeric',year:'numeric',timeZone:report.value?.privacy?.timezone||'UTC'});
const metrics=[{key:'page_views',label:'Page views',format:number},{key:'sessions',label:'Sessions',format:number},{key:'visible_ms',label:'Time on site',format:duration}];
const engagementRows=computed(()=>{const data=report.value;if(!data)return [];return data.presentations.length?data.presentations:[...data.pages].filter(row=>row.visible_ms>0).sort((a,b)=>b.visible_ms-a.visible_ms).slice(0,5).map(row=>({...row,presentation:row.path}));});
const timezoneLabel=computed(()=>report.value?.privacy.timezone==='Asia/Hong_Kong'?'Hong Kong time':(report.value?.privacy.timezone||'UTC').replaceAll('_',' '));
const currentMetric=computed(()=>metrics.find(item=>item.key===metric.value));
const technology=ref('device');
const technologyOptions=[{key:'device',label:'Device type',field:'devices'},{key:'browser',label:'Browser',field:'browser_families'},{key:'os',label:'System',field:'operating_systems'}];
const selectedTechnology=computed(()=>technologyOptions.find(option=>option.key===technology.value));
const breakdowns=computed(()=>report.value?[{title:'Referring sites',key:'source',unit:'Sessions',rows:report.value.sources},{title:'Pages explored',key:'path',unit:'Page views',rows:report.value.pages},{title:'Devices',key:technology.value,unit:'Sessions',rows:report.value[selectedTechnology.value.field]||[]},{title:'Interactions',key:'action',unit:'Events',rows:report.value.actions.filter(row=>row.action!=='performance')}]:[]);
function friendly(value){const names={'/':'Site root','/education':'Study','/fragments':'Fragments','/cv':'CV','ig':'Instagram','l.instagram.com':'Instagram links','page_view':'Page viewed','user_engagement':'Active engagement','session_start':'Visit started','first_visit':'First visit','form_start':'Form opened','/home':'Home','/about':'About','/projects':'Builds','/aipersonalarchive':'AI × Self','/research':'Research','/experience':'Experience','/views':'Views','/view':'Individual Views','/traffic':'Traffic',page:'Website pages',gallery:'The View Gallery',exhibition:'Exhibitions',article:'Articles',desktop:'Desktop',phone:'Phone',tablet:'Tablet',afterword_reached:'Exhibition completed',select_view:'View selected',reading_mode:'Reading mode',archive_select:'Archive explored',gesture:'Scene gestures'};return names[value]||String(value||'Unknown').replaceAll('_',' ');}
function barWidth(value,rows){return `${Math.max(0,Math.min(100,value/Math.max(1,...rows.map(row=>row.count))*100))}%`;}
function comparison(key){const previous=report.value?.previous?.[key]||0;if(!previous)return 'No earlier comparison';const delta=(report.value.summary[key]-previous)/previous*100;return `${Math.abs(delta).toFixed(0)}% ${delta>=0?'more':'less'} than previous period`;}
function hourValue(weekday,hour){return report.value?.hours.find(row=>row.weekday===weekday&&row.hour===hour)?.sessions||0;}
function hourIntensity(day,hour){const value=hourValue(day,hour);return value ? .25+.75*value/Math.max(1,...report.value.hours.map(row=>row.sessions)) : 0;}
function setFilter(key,value){filters.value=key?{...filters.value}:{};if(key&&value)filters.value[key]=value;else delete filters.value[key];load(true);}
function selectCountry(value){selectedCountry.value=selectedCountry.value===value?'':value;}
async function load(journeysOnly=false){journeysOnly=journeysOnly===true;controller?.abort();const current=controller=new AbortController();busy.value=!journeysOnly;filterBusy.value=journeysOnly;error.value='';filterError.value='';try{const result=await getTrafficDashboard({days:days.value,...filters.value},privateMode.value,current.signal);if(disposed||current!==controller)return;if(journeysOnly&&report.value){report.value={...report.value,sessions:result.sessions,filters:result.filters};}else report.value=result;if(!report.value.countries.some(row=>row.country===selectedCountry.value))selectedCountry.value='';}catch(e){if(current.signal.aborted||disposed)return;if(e.message==='forbidden'){clearSharedViewsAdminSession();privateMode.value=false;filters.value={};error.value='Your owner session has ended. Sign in again to continue.';if(report.value){const publicReport={...report.value};for(const key of ['sessions','filters','places','ask','search','performance','excluded','health'])delete publicReport[key];report.value=publicReport;}}else if(journeysOnly)filterError.value='Journeys could not be updated. Change a filter to retry.';else error.value='Traffic reports are temporarily unavailable.';}finally{if(current===controller){busy.value=false;filterBusy.value=false;}}}
async function openOwner(){if(privateMode.value){ownerWorkspace.value?.$el?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});return;}await openLogin();}
async function openLogin(){if(hasSharedViewsAdminSession()){privateMode.value=true;await load();if(privateMode.value)return;}returnFocus=document.activeElement;loginOpen.value=true;releaseScroll=lockBodyScroll();await nextTick();passwordInput.value?.focus();}
function closeLogin(){releaseScroll?.();releaseScroll=null;loginOpen.value=false;password.value='';loginError.value='';returnFocus?.focus();}
function trapLogin(event){const elements=[...loginForm.value.querySelectorAll('button:not(:disabled),input')],first=elements[0],last=elements.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
async function login(){loginBusy.value=true;loginError.value='';try{await loginSharedViewsAdmin(password.value);if(disposed)return;excludeOwnerBrowser(true);try{const saved=JSON.parse(localStorage.getItem('site_visitor:v1')||'null');if(saved?.id)await setTrafficExclusion(saved.id);}catch{/* Local exclusion still applies. */}privateMode.value=true;closeLogin();await load();}catch{loginError.value='Sign-in was unsuccessful. Check your password and try again.';}finally{loginBusy.value=false;}}
function signOut(){clearSharedViewsAdminSession();privateMode.value=false;filters.value={};report.value=null;load();}
onMounted(load);
onBeforeUnmount(()=>{disposed=true;controller?.abort();releaseScroll?.();password.value='';});
</script>
<style src="./traffic/traffic-dashboard.css"></style>
